#include <vector>
#include <cstdio>

using namespace std;

int a, b, k;
long long res = 0;
vector<int> primos;
vector<bool> esPrimo;

long long mcd(long long a, long long b) {
    if (b == 0) return a;
    return mcd(b, a % b);
}

long long mcm(long long a, long long b) {
    return (a / mcd(a, b)) * b;
}

void rec(int ct, int pos, long long act) {
    if (primos[pos] == k) {
        if (ct == 0 || act > b / k) return;

        act *= k;
        long long tmp = (b / act) - ((a - 1LL) / act);

        if (ct % 2 == 0)
            res += tmp;
        else
            res -= tmp;

        return;
    }

    if (act <= b / primos[pos])
        rec(ct + 1, pos + 1, act * primos[pos]);

    rec(ct, pos + 1, act);
}

