    esPrimo.assign(static_cast<size_t>(k) + 1, true);

    if (k >= 0) esPrimo[0] = false;
    if (k >= 1) esPrimo[1] = false;

    for (int i = 2; i <= k; ++i) {
        if (!esPrimo[i]) continue;

        primos.push_back(i);

        if (i <= k / i) {
            for (long long j = 1LL * i * i; j <= k; j += i)
                esPrimo[static_cast<size_t>(j)] = false;
        }
    }
}

