#include <cstdio>
#include <vector>
#include <algorithm>

using namespace std;

long long a, b, k;
long long res;
vector<int> primes;

bool isPrime(long long n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (long long i = 3; i <= n / i; i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

void rec(int pos, int count, long long product) {
    for (int i = pos; i < (int)primes.size(); ++i) {
        if (product > b / k / primes[i]) break;

        long long nextProduct = product * primes[i];
        long long divisor = nextProduct * k;
        long long amount = b / divisor - (a - 1) / divisor;

        if ((count + 1) % 2 == 0)
            res += amount;
        else
            res -= amount;

        rec(i + 1, count + 1, nextProduct);
    }
}

int main() {
    if (scanf("%lld %lld %lld", &a, &b, &k) != 3) return 0;

    if (!isPrime(k) || b < k) {
        printf("0\n");
        return 0;
    }

    if (b < k * k && a < k) {
        printf("0\n");
        return 0;
    }

    if (k == 2) {
        printf("%lld\n", b / k - (a - 1) / k);
        return 0;
    }

    long long limit = min(k - 1, b / k);
    vector<bool> sieve(limit + 1, true);

    if (limit >= 0) sieve[0] = false;
    if (limit >= 1) sieve[1] = false;

    for (long long i = 2; i <= limit / i; ++i) {
        if (sieve[i]) {
            for (long long j = i * i; j <= limit; j += i)
                sieve[j] = false;
        }
    }

    for (int i = 2; i <= limit; ++i) {
        if (sieve[i]) primes.push_back(i);
    }

    res = b / k - (a - 1) / k;
    rec(0, 0, 1);

    printf("%lld\n", res);
    return 0;
}

